create table public.f7r_receiver_controls(session_id uuid primary key references public.f7r_sessions(id) on delete cascade,enabled boolean not null default false);
create table public.f7r_receiver_status(session_id uuid primary key references public.f7r_sessions(id) on delete cascade,state text not null check(state in ('paused','waiting','publishing','stale','error')),last_seen timestamptz not null default now(),driver_count integer not null default 0 check(driver_count between 0 and 24));
alter table public.f7r_receiver_controls enable row level security;
alter table public.f7r_receiver_status enable row level security;
revoke all on public.f7r_receiver_controls,public.f7r_receiver_status from anon,authenticated;
grant select,insert,update on public.f7r_receiver_controls,public.f7r_receiver_status to authenticated;
create policy receiver_controls_read on public.f7r_receiver_controls for select to authenticated using (exists(select 1 from public.flag_admins a where a.user_id=(select auth.uid())) or exists(select 1 from public.f7r_sessions s join public.f7r_members m on m.user_id=s.publisher_id where s.id=session_id and s.publisher_id=(select auth.uid()) and s.status='live' and m.approved and m.role in ('admin','publisher')));
create policy receiver_controls_insert on public.f7r_receiver_controls for insert to authenticated with check (exists(select 1 from public.flag_admins a where a.user_id=(select auth.uid())));
create policy receiver_controls_update on public.f7r_receiver_controls for update to authenticated using (exists(select 1 from public.flag_admins a where a.user_id=(select auth.uid()))) with check (exists(select 1 from public.flag_admins a where a.user_id=(select auth.uid())));
create policy receiver_status_read on public.f7r_receiver_status for select to authenticated using (exists(select 1 from public.flag_admins a where a.user_id=(select auth.uid())) or exists(select 1 from public.f7r_sessions s join public.f7r_members m on m.user_id=s.publisher_id where s.id=session_id and s.publisher_id=(select auth.uid()) and s.status='live' and m.approved and m.role in ('admin','publisher')));
create policy receiver_status_insert on public.f7r_receiver_status for insert to authenticated with check (exists(select 1 from public.f7r_sessions s join public.f7r_members m on m.user_id=s.publisher_id where s.id=session_id and s.publisher_id=(select auth.uid()) and s.status='live' and m.approved and m.role in ('admin','publisher')));
create policy receiver_status_update on public.f7r_receiver_status for update to authenticated using (exists(select 1 from public.f7r_sessions s join public.f7r_members m on m.user_id=s.publisher_id where s.id=session_id and s.publisher_id=(select auth.uid()) and s.status='live' and m.approved and m.role in ('admin','publisher'))) with check (exists(select 1 from public.f7r_sessions s join public.f7r_members m on m.user_id=s.publisher_id where s.id=session_id and s.publisher_id=(select auth.uid()) and s.status='live' and m.approved and m.role in ('admin','publisher')));
create policy receiver_enabled_insert on public.f7r_snapshots as restrictive for insert to authenticated with check (exists(select 1 from public.f7r_receiver_controls c where c.session_id=f7r_snapshots.session_id and c.enabled));
create policy receiver_enabled_update on public.f7r_snapshots as restrictive for update to authenticated using (exists(select 1 from public.f7r_receiver_controls c where c.session_id=f7r_snapshots.session_id and c.enabled)) with check (exists(select 1 from public.f7r_receiver_controls c where c.session_id=f7r_snapshots.session_id and c.enabled));
